import json
import itertools

def compute_itinerary():
    # Input variables
    total_days = 12
    cities = ["Milan", "Seville", "Naples"]
    required_stay = {
        "Naples": 3,
        "Seville": 4,
        "Milan": 7
    }
    # Direct flights (undirected)
    direct_edges = {("Milan", "Seville"), ("Seville", "Milan"), ("Naples", "Milan"), ("Milan", "Naples")}
    # Show constraints
    show_city = "Seville"
    show_start = 9
    show_end = 12

    # Helper to check adjacency
    def is_direct(a, b):
        return (a, b) in direct_edges

    # Generate all valid sequences visiting each city exactly once with direct flights between transitions
    sequences = []
    for seq in itertools.permutations(cities, 3):
        if is_direct(seq[0], seq[1]) and is_direct(seq[1], seq[2]):
            sequences.append(seq)

    def build_presence(seq, f1, f2):
        # seq: (A, B, C), f1: day of flight A->B, f2: day of flight B->C, inclusive overlap
        presence = {d: set() for d in range(1, total_days + 1)}
        for d in range(1, total_days + 1):
            if d < f1:
                presence[d].add(seq[0])
            elif d == f1:
                presence[d].update([seq[0], seq[1]])
            elif f1 < d < f2:
                presence[d].add(seq[1])
            elif d == f2:
                presence[d].update([seq[1], seq[2]])
            else:  # d > f2
                presence[d].add(seq[2])
        return presence

    def counts_from_presence(presence):
        counts = {c: 0 for c in cities}
        for d in range(1, total_days + 1):
            for c in presence[d]:
                counts[c] += 1
        return counts

    def satisfies_show(presence):
        for d in range(show_start, show_end + 1):
            if show_city not in presence[d]:
                return False
        return True

    # Search for feasible solution
    feasible_plans = []
    for seq in sequences:
        # We need to be in show_city during show days
        # If the sequence's last city is show_city, we will be in show city from f2..end
        # If not, it's unlikely to satisfy the show constraint for all days 9..12, so skip early
        if show_city not in seq:
            continue

        # Iterate possible flight days
        for f1 in range(1, total_days + 1):
            for f2 in range(f1, total_days + 1):
                presence = build_presence(seq, f1, f2)
                if not satisfies_show(presence):
                    continue
                # Check counts match required stays exactly
                counts = counts_from_presence(presence)
                if all(counts[c] == required_stay[c] for c in required_stay):
                    # Ensure we're visiting all three cities (non-zero presence)
                    if all(counts[c] > 0 for c in cities):
                        feasible_plans.append((seq, f1, f2, presence))

    # Choose an "optimal" plan:
    # - Minimize number of flights (always 2 here)
    # - Prefer sequence where last city is show_city
    # - Prefer earliest possible first flight day (arbitrary tie-breaker)
    feasible_plans = [p for p in feasible_plans if p[0][2] == show_city]
    feasible_plans.sort(key=lambda x: (x[1], x[2]))  # earliest first flight, then earliest second flight
    if not feasible_plans:
        # As a fallback (shouldn't happen with given constraints), output empty itinerary
        return {"itinerary": []}

    seq, f1, f2, presence = feasible_plans[0]

    # Build contiguous ranges per city from presence
    def compress_city_ranges(city, presence):
        ranges = []
        start = None
        for d in range(1, total_days + 1):
            in_city = city in presence[d]
            if in_city and start is None:
                start = d
            elif not in_city and start is not None:
                ranges.append((start, d - 1))
                start = None
        if start is not None:
            ranges.append((start, total_days))
        return ranges

    entries = []
    for city in cities:
        for (s, e) in compress_city_ranges(city, presence):
            entries.append({
                "start": s,
                "end": e,
                "place": city
            })

    # Sort by start day for readability
    entries.sort(key=lambda x: (x["start"], x["end"]))

    # Format final itinerary
    itinerary = []
    for e in entries:
        itinerary.append({
            "day_range": f"Day {e['start']}-{e['end']}",
            "place": e["place"]
        })

    return {"itinerary": itinerary}

if __name__ == "__main__":
    result = compute_itinerary()
    print(json.dumps(result))
